package totem

import (
	"strings"
	"testing"

	"github.com/DATASMARTCOMCORP/traccar-api-java/server-go/internal/protocol/kit"
	"github.com/DATASMARTCOMCORP/traccar-api-java/server-go/internal/protocol/oracle"
)

// The frame decoder test compares with assertEquals, so it has no recorded calls; its
// cases are checked here (generated from the Java test), with one decoder throughout as
// in Java.
func TestFramer(t *testing.T) {
	f := Framer()
	m := oracle.NewEnv().Message(oracle.Record{})
	check := func(want string, in *kit.Buf) {
		t.Helper()
		got := ""
		if b, ok := f.Frame(m, in).(*kit.Buf); ok {
			got = b.HexDump()
		}
		if got != want {
			t.Fatalf("frame %s, want %s", got, want)
		}
	}
	_ = strings.ToLower

	check(strings.ToLower("24243030323542423836323031303033373239343836313345"), kit.Hex("24243030323542423836323031303033373239343836313345"))
	check(strings.ToLower("24243030363545363836313137323033353932363639357c3137303931323135333235372c2d37392e3337333835332c34332e3736353631392c302c302c7c3441"), kit.Hex("24243030363545363836313137323033353932363639357c3137303931323135333235372c2d37392e3337333835332c34332e3736353631392c302c302c7c3441"))
	check(strings.ToLower("24243031303841413836343234343032363036333433377c3141303030303030313430313031303130313031343131313030303032374241304535373030333130303030303030302e3030303030303030303030302e303030304e30303030302e3030303045303438313536"), kit.Hex("24243031303841413836343234343032363036333433377c3141303030303030313430313031303130313031343131313030303032374241304535373030333130303030303030302e3030303030303030303030302e303030304e30303030302e3030303045303438313536"))
	check(strings.ToLower(""), kit.Hex(""))
	check(strings.ToLower(""), kit.Hex(""))
}
